def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_re = re.compile(r"\s*(<=|>=|<>|[A-Z](?:[1-9][0-9]?)|[0-9]+|[()+*/,:=\-<>])")

    def tokenize(text):
        tokens = []
        pos = 0
        while pos < len(text):
            match = token_re.match(text, pos)
            if not match:
                raise ValueError("Invalid formula")
            tokens.append(match.group(1))
            pos = match.end()
        return tokens

    def parse(text):
        tokens = tokenize(text)
        i = 0

        def peek():
            return tokens[i] if i < len(tokens) else None

        def take(expected=None):
            nonlocal i
            token = peek()
            if token is None or (expected is not None and token != expected):
                raise ValueError("Invalid formula")
            i += 1
            return token

        def parse_formula():
            node = parse_product()
            while peek() in ("+", "-"):
                op = take()
                node = ("bin", op, node, parse_product())
            return node

        def parse_product():
            node = parse_unary()
            while peek() in ("*", "/"):
                op = take()
                node = ("bin", op, node, parse_unary())
            return node

        def parse_unary():
            if peek() == "-":
                take("-")
                return ("neg", parse_unary())
            return parse_atom()

        def parse_atom():
            token = peek()
            if token == "(":
                take("(")
                node = parse_formula()
                take(")")
                return node
            if token is None:
                raise ValueError("Invalid formula")
            if token.isdigit():
                take()
                return ("num", int(token))
            if re.fullmatch(r"[A-Z][1-9][0-9]?", token):
                take()
                return ("ref", token)
            if token in ("SUM", "MIN", "MAX"):
                take()
                take("(")
                args = []
                while True:
                    if (i + 2 < len(tokens)
                            and re.fullmatch(r"[A-Z][1-9][0-9]?", tokens[i])
                            and tokens[i + 1] == ":"
                            and re.fullmatch(r"[A-Z][1-9][0-9]?", tokens[i + 2])):
                        a = take()
                        take(":")
                        b = take()
                        args.append(("range", a, b))
                    else:
                        args.append(parse_formula())
                    if peek() != ",":
                        break
                    take(",")
                take(")")
                return ("func", token, args)
            if token == "IF":
                take()
                take("(")
                left = parse_formula()
                op = peek()
                if op not in ("=", "<>", "<", "<=", ">", ">="):
                    raise ValueError("Invalid formula")
                take()
                right = parse_formula()
                take(",")
                then_node = parse_formula()
                take(",")
                else_node = parse_formula()
                take(")")
                return ("if", op, left, right, then_node, else_node)
            raise ValueError("Invalid formula")

        tree = parse_formula()
        if i != len(tokens):
            raise ValueError("Invalid formula")
        return tree

    parsed = {
        name: (("num", int(content)) if not content.startswith("=")
               else parse(content[1:]))
        for name, content in cells.items()
    }
    values = {}
    in_progress = set()

    def evaluate_node(node):
        kind = node[0]
        if kind == "num":
            return node[1]
        if kind == "ref":
            return evaluate_cell(node[1])
        if kind == "neg":
            value = evaluate_node(node[1])
            return value if isinstance(value, str) else -value
        if kind == "bin":
            _, op, left_node, right_node = node
            left = evaluate_node(left_node)
            if isinstance(left, str):
                return left
            right = evaluate_node(right_node)
            if isinstance(right, str):
                return right
            if op == "+":
                return left + right
            if op == "-":
                return left - right
            if op == "*":
                return left * right
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if kind == "if":
            _, op, left_node, right_node, then_node, else_node = node
            left = evaluate_node(left_node)
            if isinstance(left, str):
                return left
            right = evaluate_node(right_node)
            if isinstance(right, str):
                return right
            condition = {
                "=": left == right,
                "<>": left != right,
                "<": left < right,
                "<=": left <= right,
                ">": left > right,
                ">=": left >= right,
            }[op]
            return evaluate_node(then_node if condition else else_node)

        _, function, args = node
        collected = []
        for arg in args:
            if arg[0] == "range":
                _, first, second = arg
                col1, row1 = ord(first[0]) - ord("A"), int(first[1:])
                col2, row2 = ord(second[0]) - ord("A"), int(second[1:])
                for row in range(min(row1, row2), max(row1, row2) + 1):
                    for col in range(min(col1, col2), max(col1, col2) + 1):
                        name = chr(ord("A") + col) + str(row)
                        if name in cells:
                            value = evaluate_cell(name)
                            if isinstance(value, str):
                                return value
                            collected.append(value)
            else:
                value = evaluate_node(arg)
                if isinstance(value, str):
                    return value
                collected.append(value)

        if function == "SUM":
            return sum(collected)
        if not collected:
            return 0
        return min(collected) if function == "MIN" else max(collected)

    def evaluate_cell(name):
        if name not in parsed:
            return 0
        if name in values:
            return values[name]
        if name in in_progress:
            return "#CYCLE!"
        in_progress.add(name)
        value = evaluate_node(parsed[name])
        in_progress.remove(name)
        values[name] = value
        return value

    for cell_name in cells:
        evaluate_cell(cell_name)
    return values
